/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
// css link
import { setProfile } from '../utils/APIRoutes';
import FileBase64 from 'react-file-base64';

import avatarArr from './images';

import '../styles/profile.css';

// Function
export default function SetProfile() {
  const [item, setItem] = useState({ title: '', image: '' });

  const navigate = useNavigate();
  const [avatars, setAvatars] = useState([]);
  const [selectedIndex, setSelectedIndex] = useState();
  const [selectedProfile, setSelectedProfile] = useState(undefined);
  const profilePicture = async () => {
    console.log(selectedProfile);
    if (selectedProfile === undefined) console.log('please select an image');
    else {
      const user = await JSON.parse(localStorage.getItem(''))
      const { data } = await axios.post(setProfile, selectedProfile);
    }
  };

  useEffect(() => {
    const data = [];
    for (let i = 0; i < avatarArr.length; i++) {
      const image = avatarArr[i];
      data.push(image);
    }
    setAvatars(data);
  }, []);

  return (
    <div id="avatar_component">
      <div className="title">
        <h2>Pick an image for your profile picture</h2>
      </div>
      <div className="avatars_container">
        {avatars.map((avatar, index) => {
          return (
            <div
              key={index}
              className={`avatar ${selectedIndex === index ? 'selected' : ''}`}
            >
              <img
                src={avatar}
                alt="profilePic"
                onClick={() => {
                  setSelectedProfile(avatar);
                  setSelectedIndex(index);
                }}
              />
            </div>
          );
        })}
        <div className={` own_image ${selectedIndex === 4 ? 'selected' : ''}`}>
          <ion-icon name="person-add-outline"></ion-icon>
          <FileBase64
            type="file"
            className="fileBase"
            multiple={false}
            onDone={({ base64 }) => {
              setSelectedProfile(base64);
              setSelectedIndex(4);
            }}
          />
        </div>
      </div>
      <button onClick={() => profilePicture()}>Set Profile Image</button>
    </div>
  );
}
